import pdfplumber

pdf_path = "/app/data/handbook.pdf"
with pdfplumber.open(pdf_path) as pdf:
    # Extract all text from all pages and save it
    all_text = ""
    for page_num, page in enumerate(pdf.pages, 1):
        text = page.extract_text()
        if text:
            all_text += f"\n=== PAGE {page_num} ===\n{text}\n"

    # Save to a file for easier searching
    with open('/tmp/handbook_full.txt', 'w') as f:
        f.write(all_text)

    print("Full text saved. Total pages:", len(pdf.pages))

    # Now search for specific keywords
    keywords = ['TAL', 'liquidus', '217°C', '260°C', '183°C', 'wetting time', 'peak temperature', 'cooling', 'dwell']

    for page_num, page in enumerate(pdf.pages, 1):
        text = page.extract_text()
        if text:
            for keyword in keywords:
                if keyword.lower() in text.lower():
                    print(f"\n--- PAGE {page_num} contains '{keyword}' ---")
                    # Show context around the keyword
                    lines = text.split('\n')
                    for i, line in enumerate(lines):
                        if keyword.lower() in line.lower():
                            start = max(0, i-2)
                            end = min(len(lines), i+3)
                            for j in range(start, end):
                                print(lines[j])
                            print("...")
EOF
